    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="support-card" aria-labelledby="support-heading">
        <h1 id="support-heading">Contact support</h1>
        <p class="intro">
          Send us your details and a support specialist will follow up shortly.
        </p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-required="true"
              aria-describedby="full-name-error"
            />
            <p id="full-name-error" class="error-message" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-required="true"
              aria-describedby="email-error"
            />
            <p id="email-error" class="error-message" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help phone-error"
              placeholder="(555) 123-4567"
            />
            <p id="phone-help" class="helper-text">
              Optional. Enter a 10-digit US phone number, for example (555) 123-4567 or 555-123-4567.
            </p>
            <p id="phone-error" class="error-message" aria-live="polite"></p>
          </div>

          <button type="submit">Submit</button>
          <p id="form-status" class="status-message" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const statusMessage = document.getElementById("form-status");

      const fields = {
        fullName: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            if (!value.trim()) {
              return "Full name is required.";
            }
            return "";
          },
        },
        email: {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            if (!value.trim()) {
              return "Email address is required.";
            }

            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(value.trim())) {
              return "Enter a valid email address.";
            }

            return "";
          },
        },
        phone: {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          validate(value) {
            const trimmed = value.trim();

            if (!trimmed) {
              return "";
            }

            const phonePattern = /^(?:\+1\s?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;
            if (!phonePattern.test(trimmed)) {
              return "Enter the phone number in the format (555) 123-4567 or 555-123-4567.";
            }

            return "";
          },
        },
      };

      function setFieldError(fieldConfig, message) {
        fieldConfig.error.textContent = message;
        fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
      }

      function validateField(fieldConfig) {
        const message = fieldConfig.validate(fieldConfig.input.value);
        setFieldError(fieldConfig, message);
        return message;
      }

      Object.values(fields).forEach((fieldConfig) => {
        fieldConfig.input.addEventListener("input", () => {
          validateField(fieldConfig);
          if (statusMessage.textContent) {
            statusMessage.textContent = "";
          }
        });

        fieldConfig.input.addEventListener("blur", () => {
          validateField(fieldConfig);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusMessage.textContent = "";

        const errors = Object.values(fields)
