            fieldConfig,
            message: validateField(fieldConfig),
          }))
          .filter((result) => result.message);

        if (errors.length > 0) {
          errors[0].fieldConfig.input.focus();
          return;
        }

        statusMessage.textContent = "Your support request is ready to send.";
        form.reset();
        Object.values(fields).forEach((fieldConfig) => setFieldError(fieldConfig, ""));
      });
    </script>
